type token struct {
	kind int
	text string // literal text of the token in the source
	pos  int    // 0-based byte offset of the token in the source
	val  float64
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentPart(c byte) bool { return isIdentStart(c) || isDigit(c) }

// lexNumber scans a numeric literal starting at src[start].
func lexNumber(src string, start int) (token, int, error) {
	i := start
	for i < len(src) && isDigit(src[i]) {
		i++
	}
	if i < len(src) && src[i] == '.' {
		i++
		for i < len(src) && isDigit(src[i]) {
			i++
		}
	}
	// Exponent, only consumed when it has at least one digit.
	if i < len(src) && (src[i] == 'e' || src[i] == 'E') {
		k := i + 1
		if k < len(src) && (src[k] == '+' || src[k] == '-') {
			k++
		}
		if k < len(src) && isDigit(src[k]) {
			k++
			for k < len(src) && isDigit(src[k]) {
				k++
			}
			i = k
		}
	}
	text := src[start:i]
	v, err := strconv.ParseFloat(text, 64)
	if err != nil && err.(*strconv.NumError).Err != strconv.ErrRange {
		// Cannot happen for the shapes accepted above, but stay safe.
		return token{}, start, &Error{Pos: start, Msg: fmt.Sprintf("invalid number %q", text)}
	}
	return token{kind: tkNum, text: text, pos: start, val: v}, i, nil
}

// lex scans src into a token list terminated by a tkEOF token.
func lex(src string) ([]token, error) {
	toks := make([]token, 0, 16)
	i := 0
	for i < len(src) {
		c := src[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n':
			i++
		case isIdentStart(c):
			start := i
			for i < len(src) && isIdentPart(src[i]) {
				i++
			}
			toks = append(toks, token{kind: tkIdent, text: src[start:i], pos: start})
		case isDigit(c) || (c == '.' && i+1 < len(src) && isDigit(src[i+1])):
			t, end, err := lexNumber(src, i)
			if err != nil {
				return nil, err
			}
			toks = append(toks, t)
			i = end
		default:
			two := ""
			if i+1 < len(src) {
				two = src[i : i+2]
			}
			kind, adv := tkNone, 0
			switch two {
			case "<=":
				kind, adv = tkLe, 2
			case ">=":
				kind, adv = tkGe, 2
			case "==":
				kind, adv = tkEq, 2
			case "!=":
				kind, adv = tkNe, 2
			case "&&":
				kind, adv = tkAnd, 2
			case "||":
				kind, adv = tkOr, 2
			}
			if adv == 0 {
				switch c {
				case '+':
					kind = tkPlus
				case '-':
					kind = tkMinus
				case '*':
					kind = tkStar
				case '/':
					kind = tkSlash
				case '%':
					kind = tkPercent
				case '^':
					kind = tkCaret
				case '(':
					kind = tkLParen
				case ')':
					kind = tkRParen
				case ',':
					kind = tkComma
				case '?':
					kind = tkQuestion
				case ':':
					kind = tkColon
				case '<':
					kind = tkLt
				case '>':
					kind = tkGt
				case '!':
					kind = tkNot
				}
				adv = 1
			}
			if kind == tkNone {
				r, _ := utf8.DecodeRuneInString(src[i:])
				return nil, &Error{Pos: i, Msg: fmt.Sprintf("unexpected character '%c'", r)}
			}
			toks = append(toks, token{kind: kind, text: src[i : i+adv], pos: i})
			i += adv
		}
	}
	toks = append(toks, token{kind: tkEOF, pos: len(src)})
	return toks, nil
}
