{"content":"package expr

import "fmt"

type nodeKind int

const (
	numNode nodeKind = iota
	varNode
	binNode
	unaryNode
	ternaryNode
	callNode
)

type node struct {
	kind nodeKind
	pos  int // 0-based byte offset of the operator / identifier / number
	op   int // token kind of the operator (binNode, unaryNode)
	val  float64
	name string
	l, m, r *node
	args []*node
}

type parser struct {
	src  string
	toks []token
	i    int
}

func (p *parser) peek() token { return p.toks[p.i] }
func (p *parser) next() token {
	t := p.toks[p.i]
	p.i++
	return t
}

func (p *parser) at(ops ...int) bool {
	t := p.peek()
	for _, op := range ops {
		if t.kind == op {
			return true
		}
	}
	return false
}

// unexpected reports the current token as an error.
func (p *parser) unexpected() *Error {
	t := p.peek()
	if t.kind == tkEOF {
		return &Error{Pos: len(p.src), Msg: "unexpected end of input"}
	}
	return &Error{Pos: t.pos, Msg: fmt.Sprintf("unexpected token %q", t.text)}
}

// expectToken reports an error if the current token is not the wanted one.
func (p *parser) expectToken(kind int, msg string) error {
	t := p.peek()
	if t.kind == kind {
		p.next()
		return nil
	}
	pos := len(p.src)
	if t.kind != tkEOF {
		pos = t.pos
	}
	return &Error{Pos: pos, Msg: msg}
}

// builtins maps a function name to [minArgs, maxArgs]; maxArgs of -1 means
// "at least minArgs".
var builtins = map[string][2]int{
	"abs":   {1, 1},
	"sqrt":  {1, 1},
	"round": {1, 1},
	"min":   {1, -1},
	"max":   {1, -1},
	"clamp": {3, 3},
}

// parseProgram parses one complete expression followed by end of input.
func (p *parser) parseProgram() (*node, error) {
	root, err := p.parseTernary()
	if err != nil {
		return nil, err
	}
	if p.peek().kind == tkEOF {
		return root, nil
	}
	return nil, p.unexpected()
}

// Ternary: c ? a : b, right-associative through b; a is a logical-or expr.
func (p *parser) parseTernary() (*node, error) {
	cond, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	if !p.at(tkQuestion) {
		return cond, nil
	}
	mark := p.next()
	yes, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	if err := p.expectToken(tkColon, `expected ":"`); err != nil {
		return nil, err
	}
	no, err := p.parseTernary()
	if err != nil {
		return nil, err
	}
	return &node{kind: ternaryNode, pos: mark.pos, l: cond, m: yes, r: no}, nil
}

// parseBinary parses left-associative chains of the given binary operators
// with right operands produced by sub.
func (p *parser) parseBinary(ops []int, sub func(*parser) (*node, error)) (*node, error) {
	left, err := sub(p)
	if err != nil {
		return nil, err
	}
	for p.at(ops...) {
		op := p.next()
		right, err := sub(p)
		if err != nil {
			return nil, err
		}
		left = &node{kind: binNode, pos: op.pos, op: op.kind, l: left, r: right}
	}
	return left, nil
}

func (p *parser) parseOr() (*node, error) {
	return p.parseBinary([]int{tkOr}, p.parseAnd)
}

func (p *parser) parseAnd() (*node, error) {
	return p.parseBinary([]int{tkAnd}, p.parseEq)
}

func (p *parser) parseEq() (*node, error) {
	return p.parseBinary([]int{tkEq, tkNe}, p.parseCmp)
}

func (p *parser) parseCmp() (*node, error) {
	return p.parseBinary([]int{tkLt, tkLe, tkGt, tkGe}, p.parseAdd)
}

func (p *parser) parseAdd() (*node, error) {
	return p.parseBinary([]int{tkPlus, tkMinus}, p.parseMul)
}

func (p *parser) parseMul() (*node, error) {
	return p.parseBinary([]int{tkStar, tkSlash, tkPercent}, p.parseUnary)
}

// Unary prefix operators bind looser than ^: -2^2 = -4.
func (p *parser) parseUnary() (*node, error) {
	if p.at(tkPlus, tkMinus, tkNot) {
		op := p.next()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &node{kind: unaryNode, pos: op.pos, op: op.kind, r: operand}, nil
	}
	return p.parsePower()
}

// Power: right-associative; the right operand is a unary expression so that
// 2^-1 is legal.
func (p *parser) parsePower() (*node, error) {
	base, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	if !p.at(tkCaret) {
		return base, nil
	}
	op := p.next()
	exp, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	return &node{kind: binNode, pos: op.pos, op: tkCaret, l: base, r: exp}, nil
}

func (p *parser) parsePrimary() (*node, error) {
	t := p.peek()
	switch {
	case t.kind == tkNum:
		p.next()
		return &node{kind: numNode, pos: t.pos, val: t.val}, nil
	case t.kind == tkIdent:
		p.next()
		switch t.text {
		case "true":
			return &node{kind: numNode, pos: t.pos, val: 1}, nil
		case "false":
			return &node{kind: numNode, pos: t.pos, val: 0}, nil
		}
		if p.at(tkLParen) {
			return p.parseCall(t)
		}
		return &node{kind: varNode, pos: t.pos, name: t.text}, nil
	case t.kind == tkLParen:
		p.next()
		e, err := p.parseTernary()
		if err != nil {
			return nil, err
		}
		if err := p.expectToken(tkRParen, `expected ")"`); err != nil {
			return nil, err
		}
		return e, nil
	default:
		return nil, p.unexpected()
	}
}

// parseCall parses name(arg, ...); the name token was already consumed.
func (p *parser) parseCall(nameTok token) (*node, error) {
	p.next() // "("
	var args []*node
	for {
		a, err := p.parseTernary()
		if err != nil {
			return nil, err
		}
		args = append(args, a)
		switch {
		case p.at(tkComma):
			p.next()
		case p.at(tkRParen):
			p.next()
			return p.finishCall(nameTok, args)
		default:
			pos := len(p.src)
			if p.peek().kind != tkEOF {
				pos = p.peek().pos
			}
			return nil, &Error{Pos: pos, Msg: `expected ")"`}
		}
	}
}

// finishCall validates the call name and argument count, producing compile
// errors at the position of the function name.
func (p *parser) finishCall(nameTok token, args []*node) (*node, error) {
	bounds, ok := builtins[nameTok.text]
	if !ok {
		return nil, &Error{Pos: nameTok.pos, Msg: fmt.Sprintf("unknown function %q", nameTok.text)}
	}
	n := len(args)
	if bounds[0] == bounds[1] {
		if n != bounds[0] {
			return nil, &Error{
				Pos: nameTok.pos,
				Msg: fmt.Sprintf("function %q expects %d arguments, got %d", nameTok.text, bounds[0], n),
			}
		}
	} else if n < bounds[0] {
		return nil, &Error{
			Pos: nameTok.pos,
			Msg: fmt.Sprintf("function %q expects at least %d argument, got %d", nameTok.text, bounds[0], n),
		}
	}
	return &node{kind: callNode, pos: nameTok.pos, name: nameTok.text, args: args}, nil
}
