{"content":"package expr

import (
	"fmt"
	"math"
)

// Error is a compile or runtime error located at a position in the source.
// All errors returned by this package are *Error.
type Error struct {
	Pos int    // 0-based byte offset in the source where the problem is
	Msg string
}

// Error implements the error interface: "<Pos>: <Msg>".
func (e *Error) Error() string {
	return fmt.Sprintf("%d: %s", e.Pos, e.Msg)
}

// Program is a compiled expression program.
type Program struct {
	root *node
	src  string
}

// Compile parses src once; it returns *Error on syntax errors.
func Compile(src string) (*Program, error) {
	toks, err := lex(src)
	if err != nil {
		return nil, err
	}
	p := &parser{src: src, toks: toks}
	root, err := p.parseProgram()
	if err != nil {
		return nil, err
	}
	return &Program{root: root, src: src}, nil
}

// Eval evaluates the program with the given variable values; it returns
// *Error on runtime errors.
func (p *Program) Eval(vars map[string]float64) (float64, error) {
	v, err := evalNode(p.root, vars)
	if err != nil {
		return 0, err
	}
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return 0, &Error{Pos: 0, Msg: "result is not finite"}
	}
	return v, nil
}

// Vars returns the sorted, de-duplicated variable names referenced by the
// program.
func (p *Program) Vars() []string {
	seen := make(map[string]bool)
	var walk func(n *node)
	walk = func(n *node) {
		if n.kind == varNode && !seen[n.name] {
			seen[n.name] = true
		}
		walkAll(n)
	}
	walk(p.root)
	names := make([]string, 0, len(seen))
	for name := range seen {
		names = append(names, name)
	}
	sortStrings(names)
	return names
}

// Eval compiles src and evaluates it once with vars.
func Eval(src string, vars map[string]float64) (float64, error) {
	p, err := Compile(src)
	if err != nil {
		return 0, err
	}
	return p.Eval(vars)
}

// evalNode evaluates an AST node.
func evalNode(n *node, vars map[string]float64) (float64, error) {
	switch n.kind {
	case numNode:
		return n.val, nil
	case varNode:
		v, ok := vars[n.name]
		if !ok {
			return 0, &Error{Pos: n.pos, Msg: fmt.Sprintf("unknown variable %q", n.name)}
		}
		return v, nil
	case unaryNode:
		v, err := evalNode(n.r, vars)
		if err != nil {
			return 0, err
		}
		switch n.op {
		case tkPlus:
			return v, nil
		case tkMinus:
			return -v, nil
		case tkNot:
			return truthy(-v), nil
		}
	case binNode:
		lv, err := evalNode(n.l, vars)
		if err != nil {
			return 0, err
		}
		switch n.op {
		case tkAnd:
			if lv == 0 {
				return 0, nil
			}
			rv, err := evalNode(n.r, vars)
			if err != nil {
				return 0, err
			}
			return truthy(rv), nil
		case tkOr:
			if lv != 0 {
				return 1, nil
			}
			rv, err := evalNode(n.r, vars)
			if err != nil {
				return 0, err
			}
			return truthy(rv), nil
		}
		rv, err := evalNode(n.r, vars)
		if err != nil {
			return 0, err
		}
		switch n.op {
		case tkPlus:
			return lv + rv, nil
		case tkMinus:
			return lv - rv, nil
		case tkStar:
			return lv * rv, nil
		case tkSlash:
			if rv == 0 {
				return 0, &Error{Pos: n.pos, Msg: "division by zero"}
			}
			return lv / rv, nil
		case tkPercent:
			if rv == 0 {
				return 0, &Error{Pos: n.pos, Msg: "division by zero"}
			}
			return math.Mod(lv, rv), nil
		case tkCaret:
			return math.Pow(lv, rv), nil
		case tkLt:
			return truthy(lv < rv), nil
		case tkLe:
			return truthy(lv <= rv), nil
		case tkGt:
			return truthy(lv > rv), nil
		case tkGe:
			return truthy(lv >= rv), nil
		case tkEq:
			return truthy(lv == rv), nil
		case tkNe:
			return truthy(lv != rv), nil
		}
	case ternaryNode:
		c, err := evalNode(n.l, vars)
		if err != nil {
			return 0, err
		}
		if c != 0 {
			return evalNode(n.m, vars)
		}
		return evalNode(n.r, vars)
	case callNode:
		return evalCall(n, vars)
	}
	panic(fmt.Sprintf("expr: unhandled node kind %d", n.kind))
}

// truthy maps any value to 1 (non-zero) or 0.
func truthy(v float64) float64 {
	if v != 0 {
		return 1
	}
	return 0
}

// evalCall evaluates a built-in function call; errors such as a negative
// sqrt argument are reported at the position of the function name.
func evalCall(n *node, vars map[string]float64) (float64, error) {
	args := make([]float64, len(n.args))
	for i, a := range n.args {
		v, err := evalNode(a, vars)
		if err != nil {
			return 0, err
		}
		args[i] = v
	}
	switch n.name {
	case "abs":
		return math.Abs(args[0]), nil
	case "sqrt":
		if args[0] < 0 {
			return 0, &Error{Pos: n.pos, Msg: "sqrt of negative number"}
		}
		return math.Sqrt(args[0]), nil
	case "round":
		return math.Round(args[0]), nil
	case "min":
		v := args[0]
		for _, a := range args[1:] {
			if a < v {
				v = a
			}
		}
		return v, nil
	case "max":
		v := args[0]
		for _, a := range args[1:] {
			if a > v {
				v = a
			}
		}
		return v, nil
	case "clamp":
		return math.Min(math.Max(args[0], args[1]), args[2]), nil
	}
	panic(fmt.Sprintf("expr: unhandled function %q", n.name))
}

// walkAll visits every child of n.
func walkAll(n *node) {
	for _, c := range []*node{n.l, n.m, n.r} {
		if c != nil {
			walkAll(c)
		}
	}
	for _, a := range n.args {
		walkAll(a)
	}
}
