func TestEvalArithmetic(t *testing.T) {
	cases := []struct {
		src  string
		vars map[string]float64
		want float64
	}{
		{"123", nil, 123},
		{"1.5", nil, 1.5},
		{".5", nil, 0.5},
		{"1.", nil, 1},
		{"1e3", nil, 1000},
		{"2.5E-2", nil, 0.025},
		{"2+3", nil, 5},
		{"2-3-4", nil, -5},
		{"2*3+4", nil, 10},
		{"2+3*4", nil, 14},
		{"10/4", nil, 2.5},
		{"2/3/4", nil, 1 / 6},
		{"7%3", nil, 1},
		{"-7%3", nil, -1},
