func TestShortCircuit(t *testing.T) {
	// The unneeded operand must not be evaluated: it would otherwise error.
	if got, err := Eval("0&&1/0", nil); err != nil || got != 0 {
		t.Errorf("Eval(\"0&&1/0\") = %v, %v; want 0, nil", got, err)
	}
	if got, err := Eval("1||1/0", nil); err != nil || got != 1 {
		t.Errorf("Eval(\"1||1/0\") = %v, %v; want 1, nil", got, err)
	}
	if got, err := Eval("0 ? 1/0 : 5", nil); err != nil || got != 5 {
		t.Errorf("Eval(\"0 ? 1/0 : 5\") = %v, %v; want 5, nil", got, err)
	}
	if got, err := Eval("1 ? 5 : 1/0", nil); err != nil || got != 5 {
		t.Errorf("Eval(\"1 ? 5 : 1/0\") = %v, %v; want 5, nil", got, err)
	}
	// Short-circuit also protects against unknown variables.
	if _, err := Eval("0&&y", nil); err != nil {
		t.Errorf("Eval(\"0&&y\") error: %v", err)
	}
	if _, err := Eval("1||y", nil); err != nil {
		t.Errorf("Eval(\"1||y\") error: %v", err)
	}
	// The needed operand is evaluated.
	if _, err := Eval("1&&1/0", nil); err == nil {
		t.Error("Eval(\"1&&1/0\") succeeded, want division by zero")
	}
	if _, err := Eval("1 ? 1/0 : 3", nil); err == nil {
		t.Error("Eval(\"1 ? 1/0 : 3\") succeeded, want division by zero")
	}
}

